"""Make src/tables.c from the Python Zero Ichi's own filters (so both versions use
exactly the same colour tables and palettes)."""
import sys, os
import numpy as np
K = sys.argv[1]                       # the Python zeroichi folder
OUT = sys.argv[2]
sys.path.insert(0, K)
import filters, pixelart, movie

out = ['/* Generated by gen/gen_tables.py from the Python Zero Ichi (filters.py,',
       ' * pixelart.py) - do not edit. */', '#include "looks.h"', '']


def arr(name, values, ctype="uint8_t", per=24):
    v = [int(x) for x in values]
    lines = [", ".join(str(x) for x in v[i:i + per]) for i in range(0, len(v), per)]
    out.append(f"const {ctype} {name}[{len(v)}] = {{\n    " + ",\n    ".join(lines) + "\n};")


def pal(name, p):
    r = p.rgb[0:256]; g = p.rgb[256:512]; b = p.rgb[512:768]
    def f(vals):
        return "{" + ", ".join(str(int(x)) for x in vals) + "}"
    ncol = len(set(zip(r, g, b)))
    out.append(f"const Palette {name} = {{\n  {f(r)},\n  {f(g)},\n  {f(b)},\n  {f(p.y)},\n  {f(p.u)},\n"
               f"  {f(p.v)},\n  {f(p.gif_index)},\n  {int(bool(p.gray))}, {ncol}\n}};")


arr("T_MONO", filters.MONO)
arr("T_CROSS_R", filters.CROSS_R)
arr("T_CROSS_G", filters.CROSS_G)
arr("T_CROSS_B", filters.CROSS_B)
arr("T_HOLGA_C", filters.T_HOLGA_C)
arr("T_HC_Y", filters.T_HC_Y)
arr("T_HC_CB", filters.T_HC_CB)
arr("T_HC_CR", filters.T_HC_CR)
arr("T_GB_CONTRAST", filters.GB_CONTRAST)
pal("PAL_GRAY", filters._PAL_GRAY)
pal("PAL_HOLGA", filters.PAL_HOLGA)
arr("T_HICON", filters.HICON)
pal("PAL_THERMAL", filters.PAL_THERMAL)
# Zero Ichi (v52: colour film - see filters.py and gen/gen_zifilm.py)
arr("T_ZI_TONE", filters.ZI_TONE)
arr("T_ZI_YC", filters.T_ZI_YC)
arr("T_ZI_EXP", filters.T_ZI_EXP)
arr("ZI_SY", filters.ZI_SY, "int16_t")
arr("ZI_TU", filters.ZI_TU, "int8_t")
arr("ZI_TV", filters.ZI_TV, "int8_t")
arr("ZI_CU", filters.ZI_CU, "int8_t", per=32)
arr("ZI_CV", filters.ZI_CV, "int8_t", per=32)
pal("PAL_GB_GREEN", filters.PAL_GB_GREEN)
pal("PAL_GB_GRAY", filters.PAL_GB_GRAY)
# 8mm: faded colour table for each flicker step (gain rounded to 0.01)
em = []
for k in range(17):
    em += filters._em_table_c(0.90 + k * 0.01)
arr("T_EM", em)
# 16-Bit palettes
for i, name in enumerate(pixelart.ORDER):
    pp = filters._PixelPal(name)
    pal(f"PAL_PIXEL_{i}", pp.pal)
    arr(f"LUT_PIXEL_{i}", pp.lut, per=48)
    out.append(f"const int AMP_PIXEL_{i} = {pp.amp};")
    out.append(f"const int NCOL_PIXEL_{i} = {len(pixelart.colors(name))};")
# the standard JPEG Huffman tables (hardware MJPEG frames leave them out)
arr("JPEG_STD_DHT", movie._standard_huffman())
out.append(f"const int JPEG_STD_DHT_LEN = {len(movie._standard_huffman())};")
open(OUT, "w").write("\n".join(out) + "\n")
print("written", OUT)
